Select DocumentType, SET_Bucket.Description,CustomerID,CustomerName as SupplierName ,'' as CurrencyName,InvoiceNumber,InvoiceDate,0 as Days, sum(SaleAmount) as InvoiceAmount,0 as Amount, sum(Receive) as PaymentAmount ,(abs(sum(SaleAmount)) - abs(sum(Receive))) Balance from ( Select distinct Set_DocumentTYpe.DocumentType ,SAL_InvoiceHeader.CustomerID,AR_SET_Customer.CustomerName,SAL_InvoiceHeader.InvoiceDate ,SAL_InvoiceHeader.InvoiceNumber ,SAL_InvoiceHeader.AmountPaid as SaleAmount ,0 as Receive from SAL_InvoiceHeader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = SAL_InvoiceHeader.invoiceType Inner Join Fabrics_SAL_InvoiceDetail on Fabrics_SAL_InvoiceDetail.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID Inner Join Fabrics_CustomerChallanInfo on Fabrics_CustomerChallanInfo.Lotno = Fabrics_SAL_InvoiceDetail.LotNo Left Join Set_Color on Set_Color.ColorID = Fabrics_CustomerChallanInfo.ColorID Left Join SET_Fabric on SET_Fabric.FabricID = Fabrics_CustomerChallanInfo.FabricTypeID left Join Fabrics_SAL_InvoiceProcessRates on Fabrics_SAL_InvoiceProcessRates.InvoiceHeaderID = SAL_InvoiceHeader.InvoiceID Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = SAL_InvoiceHeader.CustomerID Where SAL_InvoiceHeader.Status=1 And convert(date,SAL_InvoiceHeader.InvoiceDate) <= @FromDate {0} Group By AR_SET_Customer.CustomerName ,SAL_InvoiceHeader.InvoiceNumber ,SAL_InvoiceHeader.CustomerID,SAL_InvoiceHeader.InvoiceDate,Fabrics_SAL_InvoiceDetail.LotNo ,Set_Color.ColorName, SET_Fabric.FabricName ,Fabrics_CustomerChallanInfo.FabricWeight ,SAL_InvoiceHeader.AmountPaid ,Set_DocumentTYpe.DocumentType
union all
select Set_DocumentTYpe.DocumentType, ar_receipttransactionHEader.CustomerID,AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceDate,SAL_InvoiceHeader.invoiceNumber ,0 as SaleAmount ,round(AR_ReceiptInvoicesDetail.Amount,0) as Receive
from ar_receipttransactionHEader inner join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptAccountsDetail.TransactionType = 'Debit' and AR_ReceiptAccountsDetail.CodeCombinationID = '03-02-06-02-004' and AR_ReceiptAccountsDetail.Status = 1 inner join AR_ReceiptInvoicesDetail on AR_ReceiptInvoicesDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptInvoicesDetail.Status = 1 inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = AR_ReceiptInvoicesDetail.InvoiceHeaderID inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = SAL_InvoiceHeader.invoicetype Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = ar_receipttransactionHEader.CustomerID where invoiceFor = 'SRO' AND ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate and ar_receipttransactionHEader.Status = 1 {0}
union all select Set_DocumentTYpe.DocumentType, ar_receipttransactionHEader.CustomerID,AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceDate,SAL_InvoiceHeader.invoiceNumber ,0 as SaleAmount ,AR_ReceiptInvoicesDetail.Amount as Receive
from ar_receipttransactionHEader inner join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptAccountsDetail.TransactionType = 'Debit' and AR_ReceiptAccountsDetail.CodeCombinationID = '03-02-04-05-005' and AR_ReceiptAccountsDetail.Status = 1 inner join AR_ReceiptInvoicesDetail on AR_ReceiptInvoicesDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptInvoicesDetail.Status = 1 inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = AR_ReceiptInvoicesDetail.InvoiceHeaderID
inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = SAL_InvoiceHeader.invoicetype Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = ar_receipttransactionHEader.CustomerID where invoiceFor = 'InComeTAX' AND ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID and ar_receipttransactionHEader.Status = 1 AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate {0}
union all
select Set_DocumentTYpe.DocumentType, ar_receipttransactionHEader.CustomerID,AR_SET_Customer.CustomerName, SAL_InvoiceHeader.InvoiceDate,SAL_InvoiceHeader.invoiceNumber ,0 as SaleAmount ,AR_ReceiptInvoicesDetail.Amount as Receive from ar_receipttransactionHEader inner join AR_ReceiptBanksDetail on AR_ReceiptBanksDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptBanksDetail.TransactionType = 'Debit' and AR_ReceiptBanksDetail.Status = 1 inner join AR_ReceiptInvoicesDetail on AR_ReceiptInvoicesDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptInvoicesDetail.Status = 1 inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = AR_ReceiptInvoicesDetail.InvoiceHeaderID inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = SAL_InvoiceHeader.invoicetype
Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = ar_receipttransactionHEader.CustomerID where invoiceFor = 'Customer' AND ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID and ar_receipttransactionHEader.Status = 1 AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate {0}
union all select distinct Set_DocumentTYpe.DocumentType, ar_receipttransactionHEader.CustomerID,AR_SET_Customer.CustomerName, ar_receipttransactionHEader.DocumentDate as InvoiceDate,ar_receipttransactionHEader.DocumentNo as invoiceNumber ,AR_ReceiptCustomerDetail.Amount as SaleAmount ,0 as Receive from ar_receipttransactionHEader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = ar_receipttransactionHEader.DocumentTypeID inner join AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptCustomerDetail.Status = 1 inner join AR_ReceiptInvoicesDetail on AR_ReceiptInvoicesDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptInvoicesDetail.Status = 1 inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = AR_ReceiptInvoicesDetail.InvoiceHeaderID Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID where AR_ReceiptCustomerDetail.TransactionType = 'Debit' AND ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID and ar_receipttransactionHEader.Status = 1 AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate {0} and ar_receipttransactionHEader.DocumentTypeID = 21
union all select distinct Set_DocumentTYpe.DocumentType, ar_receipttransactionHEader.CustomerID,AR_SET_Customer.CustomerName, ar_receipttransactionHEader.DocumentDate as InvoiceDate,ar_receipttransactionHEader.DocumentNo as invoiceNumber ,0 as SaleAmount ,AR_ReceiptCustomerDetail.Amount as Receive from ar_receipttransactionHEader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = ar_receipttransactionHEader.DocumentTypeID inner join AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptCustomerDetail.Status = 1 inner join AR_ReceiptInvoicesDetail on AR_ReceiptInvoicesDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptInvoicesDetail.Status = 1 inner join SAL_InvoiceHeader on SAL_InvoiceHeader.InvoiceID = AR_ReceiptInvoicesDetail.InvoiceHeaderID Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID where AR_ReceiptCustomerDetail.TransactionType = 'Credit' AND ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID and ar_receipttransactionHEader.Status = 1 AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate {0} and ar_receipttransactionHEader.DocumentTypeID = 21
union all
select Set_DocumentTYpe.DocumentType, AR_ReceiptCustomerDetail.CustomerID,AR_SET_Customer.CustomerName, DocumentDate as InvoiceDate,ar_receipttransactionHEader.documentNO as InvoiceNumber ,0 as SaleAmount ,AR_ReceiptCustomerDetail .Amount as Receive from ar_receipttransactionHEader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = ar_receipttransactionHEader.DocumentTypeID inner join AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptCustomerDetail.Status = 1 Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID where ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate and ar_receipttransactionHEader.Documenttypeid<>21 and AR_ReceiptCustomerDetail.TransactionType = 'Credit' and ar_receipttransactionHEader.Status = 1 {0}
union all
select Set_DocumentTYpe.DocumentType, AR_ReceiptCustomerDetail.CustomerID,AR_SET_Customer.CustomerName, DocumentDate as InvoiceDate,ar_receipttransactionHEader.documentNO as InvoiceNumber ,AR_ReceiptCustomerDetail.Amount as SaleAmount ,0 as Receive from ar_receipttransactionHEader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = ar_receipttransactionHEader.DocumentTypeID inner join AR_ReceiptCustomerDetail on AR_ReceiptCustomerDetail.ReceiptHeaderID = ar_receipttransactionHEader.ReceiptTransactionID and AR_ReceiptCustomerDetail.Status = 1 Left Join AR_SET_Customer on AR_SET_Customer.CustomerID = AR_ReceiptCustomerDetail.CustomerID where ar_receipttransactionHEader.CompanyID in @CompanyID AND ar_receipttransactionHEader.PeriodID = @PeriodID AND convert(date,ar_receipttransactionHEader.DocumentDate) <= @FromDate and ar_receipttransactionHEader.Documenttypeid<>21 and AR_ReceiptCustomerDetail.TransactionType = 'Debit' and ar_receipttransactionHEader.Status = 1 {0}
union all select Set_DocumentTYpe.DocumentType, AR_SET_Customer.CustomerID,AR_SET_Customer.CustomerName, DocumentDate as InvoiceDate,Ap_PaymentHeader.DocumentNO as InvoiceNumber ,AP_PaymentSupplierDetail.Amount as SaleAmount ,0 as Receive from Ap_PaymentHeader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = Ap_PaymentHeader.DocumentTypeID inner join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = Ap_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.Status = 1 inner Join AR_SET_Customer on AR_SET_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID where Ap_PaymentHeader.CompanyID in @CompanyID AND Ap_PaymentHeader.PeriodID = @PeriodID AND convert(date,Ap_PaymentHeader.DocumentDate) <= @FromDate and AP_PaymentSupplierDetail.TransactionType = 'Debit' and Ap_PaymentHeader.Status = 1 {0}
union all select Set_DocumentTYpe.DocumentType, AR_SET_Customer.CustomerID,AR_SET_Customer.CustomerName, DocumentDate as InvoiceDate,Ap_PaymentHeader.DocumentNO as InvoiceNumber ,0 as SaleAmount ,AP_PaymentSupplierDetail.Amount as Receive from Ap_PaymentHeader inner join Set_DocumentTYpe on Set_DocumentTYpe.DocumentTypeID = Ap_PaymentHeader.DocumentTypeID inner join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = Ap_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.Status = 1 inner Join AR_SET_Customer on AR_SET_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID where Ap_PaymentHeader.CompanyID in @CompanyID AND Ap_PaymentHeader.PeriodID = @PeriodID AND convert(date,Ap_PaymentHeader.DocumentDate) <= @FromDate and AP_PaymentSupplierDetail.TransactionType = 'Credit' and Ap_PaymentHeader.Status = 1 {0}
) as Tab1 INNER JOIN SET_Bucket ON SET_Bucket.CompanyID = 1 and SET_Bucket.Status = 1 and SET_Bucket.IsActive = 1 where (DATEDIFF(day, Tab1.InvoiceDate, @FromDate) between FromNoOfDays AND tonoofdays or (tonoofdays is null AND DATEDIFF(day, Tab1.InvoiceDate, @FromDate) >= FromNoOfDays))
group by DocumentType,CustomerID,CustomerName,InvoiceDate,InvoiceNumber,SET_Bucket.Description Order By DocumentType, Tab1.CustomerID, Tab1.CustomerName ,Tab1.InvoiceNumber asc
